#include <Arduino.h>
#include <BleMouse.h>

// Bluetooth device name
BleMouse bleMouse("Prefire ESP32", "Prefire", 100);

void setup() {
  // USB serial connection to Python
  Serial.begin(115200);

  // Start Bluetooth HID mouse
  bleMouse.begin();

  Serial.println("Prefire ESP32 started.");
  Serial.println("Bluetooth mouse: Prefire ESP32");
  Serial.println("Waiting for Bluetooth connection...");
}

void loop() {
  // Only accept commands when connected to the PC via Bluetooth
  if (bleMouse.isConnected()) {

    while (Serial.available() > 0) {
      char command = Serial.read();

      if (command == '1') {
        bleMouse.click(MOUSE_LEFT);
        Serial.println("CLICK");
      }
    }
  }

  delay(1);
}
